// Build JQL values in the exact format nFeed stores: "Acme Trading Co (62990) [62990]"
const BATCH_SIZE = 40;   // 246 companies -> 7 batches; a bad company value only fails its own batch
const PROJECTS   = ['Alpha', 'Beta'];  // project NAMES as shown in Jira
const FIELD      = 'cf[15922]';               // same field as "Company" in JQL

// JQL string literals use double quotes; escape backslashes and quotes inside values
const escapeJql = (s) => String(s).replace(/\\/g, '\\\\').replace(/"/g, '\\"');

const toJiraValue = (name, id) => {
  // If the DB name already ends with "(62990)", don't add it twice
  const base = name.replace(new RegExp(`\\s*\\(${id}\\)\\s*$`), '');
  return `${base} (${id}) [${id}]`;
};

// one entry per company_id
const byId = new Map();
for (const { json: r } of $input.all()) {
  const id = String(r.company_id ?? '').trim();
  const name = String(r.company_name ?? '').trim();
  if (id && name && !byId.has(id)) byId.set(id, toJiraValue(name, id));
}
const values = [...byId.values()];

const projectClause = PROJECTS.map(p => `"${p}"`).join(', ');
const batches = [];
for (let i = 0; i < values.length; i += BATCH_SIZE) {
  const chunk = values.slice(i, i + BATCH_SIZE);
  const list = chunk.map(v => `"${escapeJql(v)}"`).join(', ');
  batches.push({ json: {
    batch: batches.length + 1,
    companyCount: chunk.length,
    jql: `project in (${projectClause}) AND ${FIELD} in (${list}) ORDER BY key ASC`
  }});
}
return batches;

// Input: the Jira node's output (one item per ticket).
// Turns everything Jira returned into ONE SQL statement that saves results in Postgres.
// Always returns exactly one item, so the save step always runs, even with 0 tickets or Jira errors.
const TABLE = 'uk_clientco_test.jira_ticket_results';
const RUN_AT = $now.toISO();

const COMPANY_IDS = new Set(
  $('Get companies').all()
    .map(i => String(i.json.company_id ?? '').trim().replace(/\.0+$/, ''))
    .filter(Boolean)
);
const PROJECTS = ['alpha', 'beta'];

const companyValues = (v) => {
  if (v === null || v === undefined) return [];
  return (Array.isArray(v) ? v : [v])
    .map(c => (c && typeof c === 'object') ? (c.value ?? c.name ?? c.id ?? JSON.stringify(c)) : c)
    .filter(c => c !== null && c !== undefined && c !== '')
    .map(c => String(c).trim());
};

const rows = [];
const seen = new Set();
let items = 0, errors = 0;

// The Jira node outputs ONE ITEM PER TICKET (it already did the paging for us)
for (const item of $input.all()) {
  const t = item.json;

  // Error from a batch (needs Settings -> On Error -> Continue on the Jira node)
  if (t.error) {
    errors++;
    rows.push({ issue_key: 'JIRA_ERROR', reason: JSON.stringify(t.error).slice(0, 2000) });
    continue;
  }
  if (!t.key) continue;           // empty item from "Always Output Data" when nothing matched
  items++;
  if (seen.has(t.key)) continue;  // same ticket can match two batches
  seen.add(t.key);

  const f = t.fields || {};
  const project = f.project?.name ?? '';
  const companies = companyValues(f.customfield_15922);
  const ids = companies.flatMap(c => c.match(/\d+/g) || []);

  let reason = '';
  if (!PROJECTS.includes(project.toLowerCase())) reason = `project "${project}" not in Alpha/Beta`;
  else if (companies.length === 0) reason = 'Company field is empty';
  else if (!ids.some(id => COMPANY_IDS.has(id))) reason = 'company id not in jira_company_mapping';

  rows.push({
    issue_key: t.key,
    project,
    issuetype: f.issuetype?.name ?? '',
    summary: f.summary ?? '',
    company: companies.join(', '),
    in_scope: reason === '' ? 'yes' : 'no',
    reason
  });
}

// One summary row per run: what was sent and what came back
const jql = $('Build JQL batches').all().map(i => i.json.jql);
rows.unshift({
  issue_key: 'RUN_SUMMARY',
  summary: `companies=${COMPANY_IDS.size} batches=${jql.length} tickets_returned=${items} unique_tickets=${seen.size} batch_errors=${errors}`,
  reason: (jql[0] || '').slice(0, 2000)
});

for (const r of rows) r.run_at = RUN_AT;

// Dollar-quoting ($j$ ... $j$) means quotes/apostrophes in summaries can never break the SQL
const json = JSON.stringify(rows).split('$j$').join('$ j$');

const sql = `
CREATE TABLE IF NOT EXISTS ${TABLE} (
  run_at     timestamptz,
  issue_key  text,
  project    text,
  issuetype  text,
  summary    text,
  company    text,
  in_scope   text,
  reason     text
);
-- Replace the previous results with this run's results in ONE statement:
-- the DELETE and INSERT succeed or fail together, so the table is never left empty
WITH cleared AS (
  DELETE FROM ${TABLE}
)
INSERT INTO ${TABLE} (run_at, issue_key, project, issuetype, summary, company, in_scope, reason)
SELECT run_at::timestamptz, issue_key, project, issuetype, summary, company, in_scope, reason
FROM json_to_recordset($j$${json}$j$::json)
  AS x(run_at text, issue_key text, project text, issuetype text, summary text, company text, in_scope text, reason text);
`;

return [{ json: { sql, rows_saved: rows.length, run_at: RUN_AT } }];
